import {
  Entity,
  PrimaryColumn,
  Column,
  CreateDateColumn,
  UpdateDateColumn,
  ManyToOne,
  JoinColumn,
  Index,
} from 'typeorm';
import { User } from '../../users/entities/user.entity';

/**
 * A study plan the student made with the AI planner ("AI Study Plan"): the answers they gave
 * (`form`) and the plan that came back (`plan`, month by month). The id is generated by the app
 * (a UUID) so a plan can be saved again as it is edited or extended.
 */
@Entity('study_plans')
@Index('IDX_study_plans_user', ['user_id', 'created_at'])
export class StudyPlan {
  @PrimaryColumn('uuid')
  id: string;

  @Column()
  user_id: number;

  @ManyToOne(() => User, { onDelete: 'CASCADE' })
  @JoinColumn({
    name: 'user_id',
    foreignKeyConstraintName: 'FK_study_plans_user',
  })
  user?: User;

  @Column({ type: 'varchar', length: 255 })
  name: string;

  @Column({ type: 'jsonb', default: () => "'{}'" })
  form: Record<string, unknown>;

  @Column({ type: 'jsonb', default: () => "'{}'" })
  plan: Record<string, unknown>;

  @CreateDateColumn({ type: 'timestamptz' })
  created_at: Date;

  @UpdateDateColumn({ type: 'timestamptz' })
  updated_at: Date;
}
